import java.util.*;
import java.io.*;

public class Main {
    // Return the output lines: the total size first, then one "id size" line per reported collection.
    static List<String> topCollections(long[] sizes, List<List<String>> memberships, int top) {
        // Write your solution here
        List<String> lines = new ArrayList<>();
        lines.add("0");
        return lines;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int f = Integer.parseInt(st.nextToken());
        int top = Integer.parseInt(st.nextToken());
        long[] sizes = new long[f];
        List<List<String>> memberships = new ArrayList<>();
        for (int i = 0; i < f; i++) {
            sizes[i] = Long.parseLong(st.nextToken());
            int k = Integer.parseInt(st.nextToken());
            List<String> ids = new ArrayList<>();
            for (int j = 0; j < k; j++) ids.add(st.nextToken());
            memberships.add(ids);
        }
        StringBuilder sb = new StringBuilder();
        for (String s : topCollections(sizes, memberships, top)) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
